#include "stdlib/stats/base/dists/log-logistic/logcdf.h"
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/math/base/special/log1p.h"
#include "stdlib/math/base/special/ln.h"
#include "stdlib/math/base/special/pow.h"
#include "stdlib/constants/float64/ninf.h"

/**
* Evaluates the natural logarithm of the cumulative distribution function (CDF) for a log-logistic distribution
* with scale parameter `alpha` and shape parameter `beta` at a value `x`.
*
* @param x        input value
* @param alpha    scale parameter
* @param beta     shape parameter
* @return         evaluated logCDF
*
* @example
* double y = stdlib_base_dists_log_logistic_logcdf( 2.0, 1.0, 1.0 );
* // returns ~-0.405
*/
double stdlib_base_dists_log_logistic_logcdf( const double x, const double alpha, const double beta ) {
	double base;
	double xb;
	if (
		stdlib_base_is_nan( x ) ||
		stdlib_base_is_nan( alpha ) ||
		stdlib_base_is_nan( beta ) ||
		alpha <= 0.0 ||
		beta <= 0.0
	) {
		return 0.0 / 0.0; // NaN
	}
	if ( x <= 0.0 ) {
		return STDLIB_CONSTANT_FLOAT64_NINF;
	}
	// Select the algebraically equivalent form which keeps the intermediate power bounded, thus avoiding overflow to infinity as `x` grows large, while preserving accuracy in the lower tail...
	if ( x <= alpha ) {
		base = x / alpha;
		xb = stdlib_base_pow( base, beta );
		return ( beta * stdlib_base_ln( base ) ) - stdlib_base_log1p( xb );
	}
	return -stdlib_base_log1p( stdlib_base_pow( alpha / x, beta ) );
}
